/**
 * @description Scheduled and batch work: the nightly clean-up (Success transactions past the event's retention are
 * deleted, never when the event has no retention; Sent ones with no callback are marked Failed) and bulk retry by
 * hand. The automatic retry of temporary failures is IntegrationHubAutoRetry; scheduleAll schedules it too. Each
 * clean-up saves its result on the Integration Hub Settings org default.
 * @group Integration Hub
 */
public with sharing class IntegrationHubMaintenance implements Schedulable, Database.Batchable<SObject>, Database.Stateful {

    @TestVisible
    private static final String CLEANUP = 'cleanup';
    private static final String RETRY = 'retry';
    /** @description Name of the nightly clean-up job (Setup > Scheduled Jobs). */
    public static final String CLEANUP_JOB = 'Integration Hub Cleanup';

    private final String mode;
    private final String filter;
    private final Map<String, Object> binds;
    /** Success transactions deleted by this clean-up run (kept between batch chunks). */
    @TestVisible
    private Integer deleted = 0;
    /** Sent transactions this clean-up run marked Failed for a missing callback. */
    @TestVisible
    private Integer timedOut = 0;

    @TestVisible
    private IntegrationHubMaintenance(String jobMode, String whereClause, Map<String, Object> bindValues) {
        mode = jobMode;
        filter = whereClause;
        binds = bindValues;
    }

    /**
     * @description Schedules every Integration Hub job that is missing: the nightly clean-up at 02:00 and the four
     * auto-retry jobs (every 15 minutes). A job that exists is left alone, so it can be run again safely, for example
     * after a sandbox refresh.
     */
    public static void scheduleAll() {
        if (!isScheduled()) {
            System.schedule(CLEANUP_JOB, '0 0 2 * * ?', new IntegrationHubMaintenance(CLEANUP, null, null));
        }
        IntegrationHubAutoRetry.scheduleJobs();
    }

    /**
     * @description True when the nightly clean-up job exists (a sandbox refresh removes it).
     * @return whether it is scheduled
     */
    public static Boolean isScheduled() {
        return IntegrationHubData.countQuery('SELECT COUNT() FROM CronTrigger WHERE CronJobDetail.Name = :name',
            new Map<String, Object>{ 'name' => CLEANUP_JOB }) > 0;
    }

    /**
     * @description Marks Failed or Abandoned outbound transactions for retry now, with a fresh payload; a planned
     * automatic retry is cleared. The transaction trigger then sends them.
     * @param ids the transactions
     * @return how many were marked
     */
    public static Integer retryNow(List<Id> ids) {
        List<IH_Transaction__c> rows = retryRows((List<IH_Transaction__c>) IntegrationHubData.query(
            'SELECT Id FROM IH_Transaction__c WHERE Id IN :ids AND Direction__c = :dir AND Status__c IN :bad',
            new Map<String, Object>{ 'ids' => ids, 'dir' => IntegrationHub.OUTBOUND, 'bad' => badStatuses() }));
        IntegrationHubData.updateEach(rows);
        return rows.size();
    }

    /**
     * @description Starts a batch that marks matching transactions for retry; the transaction trigger sends each chunk.
     * @param whereClause SOQL condition using only bind variables, e.g. Status__c IN :bad
     * @param bindValues the bind values
     * @return the batch job Id
     */
    public static Id retryInBackground(String whereClause, Map<String, Object> bindValues) {
        return Database.executeBatch(new IntegrationHubMaintenance(RETRY, whereClause, bindValues), 200);
    }

    /**
     * @description Statuses a retry applies to.
     * @return Failed and Abandoned
     */
    public static List<String> badStatuses() {
        return new List<String>{ IntegrationHub.STATUS_FAILED, IntegrationHub.STATUS_ABANDONED };
    }

    /**
     * @description Scheduled run.
     * @param sc the schedulable context
     */
    public void execute(SchedulableContext sc) {
        IntegrationHubMaintenance job = new IntegrationHubMaintenance(CLEANUP, null, null);
        job.timedOut = timeoutCallbacks();
        Database.executeBatch(job, 200);
    }

    /**
     * @description Batch start.
     * @param bc the batch context
     * @return the records to process
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        if (mode == RETRY) {
            return IntegrationHubData.locator('SELECT Id FROM IH_Transaction__c WHERE ' + filter, binds);
        }
        return IntegrationHubData.locator(
            'SELECT Id, Event__c, Completed_At__c FROM IH_Transaction__c WHERE Status__c = :s AND Completed_At__c < :cutoff',
            new Map<String, Object>{ 's' => IntegrationHub.STATUS_SUCCESS, 'cutoff' => System.now().addDays(-1) });
    }

    /**
     * @description Batch chunk: marks for retry, or deletes Success transactions past their retention.
     * @param bc the batch context
     * @param scope the records
     */
    public void execute(Database.BatchableContext bc, List<SObject> scope) {
        if (mode == RETRY) {
            IntegrationHubData.updateEach(retryRows((List<IH_Transaction__c>) scope));
            return;
        }
        Map<Id, Decimal> retention = eventNumbers(scope, 'Retention_Days__c');
        List<SObject> old = new List<SObject>();
        for (SObject row : scope) {
            IH_Transaction__c t = (IH_Transaction__c) row;
            Datetime cutoff = retentionCutoff(retention.get(t.Event__c), System.now());
            if (cutoff != null && t.Completed_At__c < cutoff) {
                old.add(t);
            }
        }
        deleted += old.size() - IntegrationHubData.deleteEach(old).errors.size();
    }

    /**
     * @description Batch end. A clean-up saves its result; a retry has nothing to do (the transaction trigger sent
     * each chunk).
     * @param bc the batch context
     */
    public void finish(Database.BatchableContext bc) {
        if (mode == CLEANUP) {
            saveResult(deleted, timedOut, System.now());
        }
    }

    /**
     * @description Saves the result of a clean-up run on the Integration Hub Settings org default.
     * @param deletedCount Success transactions deleted
     * @param timedOutCount Sent transactions marked Failed
     * @param finishedAt when the run finished
     */
    @TestVisible
    private static void saveResult(Integer deletedCount, Integer timedOutCount, Datetime finishedAt) {
        IH_Settings__c s = IH_Settings__c.getOrgDefaults();
        s.SetupOwnerId = UserInfo.getOrganizationId();
        s.Last_Cleanup_At__c = finishedAt;
        s.Last_Cleanup_Deleted__c = deletedCount;
        s.Last_Cleanup_Timed_Out__c = timedOutCount;
        IntegrationHubData.upsertAll(new List<IH_Settings__c>{ s });
    }

    private static List<IH_Transaction__c> retryRows(List<IH_Transaction__c> txns) {
        List<IH_Transaction__c> rows = new List<IH_Transaction__c>();
        for (IH_Transaction__c t : txns) {
            rows.add(new IH_Transaction__c(Id = t.Id, Status__c = IntegrationHub.STATUS_RETRY, Next_Retry_At__c = null,
                Rebuild_Payload__c = true, Error_Message__c = null, Error_Summary__c = null));
        }
        return rows;
    }

    private static Integer timeoutCallbacks() {
        List<IH_Transaction__c> sent = (List<IH_Transaction__c>) IntegrationHubData.query(
            'SELECT Id, Event__c, Last_Attempt__c FROM IH_Transaction__c WHERE Status__c = :s AND Last_Attempt__c < :cutoff LIMIT 10000',
            new Map<String, Object>{ 's' => IntegrationHub.STATUS_SENT, 'cutoff' => System.now().addHours(-1) });
        Map<Id, Decimal> hours = eventNumbers(sent, 'Callback_Timeout_Hours__c');
        List<IH_Transaction__c> late = new List<IH_Transaction__c>();
        for (IH_Transaction__c t : sent) {
            if (t.Last_Attempt__c < callbackCutoff(hours.get(t.Event__c), System.now())) {
                IntegrationHubOutcome.failPermanent(t, 'No callback received.');
                late.add(t);
            }
        }
        return late.size() - IntegrationHubData.updateEach(late).errors.size();
    }

    /**
     * @description Success transactions completed before this moment are past retention.
     * @param retentionDays the event's Retention_Days__c; blank means keep for ever
     * @param now the current time
     * @return the cut-off, or null when nothing is deleted
     */
    @TestVisible
    private static Datetime retentionCutoff(Decimal retentionDays, Datetime now) {
        return retentionDays == null ? null : now.addDays(-retentionDays.intValue());
    }

    /**
     * @description Sent transactions last attempted before this moment have waited too long for their callback.
     * @param timeoutHours the event's Callback_Timeout_Hours__c, or null for 24
     * @param now the current time
     * @return the cut-off
     */
    @TestVisible
    private static Datetime callbackCutoff(Decimal timeoutHours, Datetime now) {
        Decimal hours = timeoutHours == null ? 24 : timeoutHours;
        return now.addHours(-hours.intValue());
    }

    private static Map<Id, Decimal> eventNumbers(List<SObject> txns, String fieldName) {
        Set<Id> eventIds = new Set<Id>();
        for (SObject t : txns) {
            eventIds.add((Id) t.get('Event__c'));
        }
        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (IH_Event__c ev : (List<IH_Event__c>) IntegrationHubData.query(
                'SELECT Id, Retention_Days__c, Callback_Timeout_Hours__c FROM IH_Event__c WHERE Id IN :ids',
                new Map<String, Object>{ 'ids' => eventIds })) {
            if (ev.get(fieldName) != null) {
                result.put(ev.Id, (Decimal) ev.get(fieldName));
            }
        }
        return result;
    }
}
